import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int n = Integer.parseInt(reader.readLine());
        String data = reader.readLine();

        String regex = "\\([\\w_]*\\)";
        String[] splitParts = data.split(regex);
        int maxWordLength = 0;
        for (String part : splitParts) {
            int maxInPart = Arrays.stream(part.split("_"))
                                .mapToInt(String::length)
                                .max()
                                .orElse(0);
            if (maxInPart > maxWordLength) {
                maxWordLength = maxInPart;
            }
        }

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(data);
        long insideWordsCount = 0;
        while (matcher.find()) {
            String inside = matcher.group().substring(1, matcher.group().length() - 1);
            insideWordsCount += Arrays.stream(inside.split("_"))
                                       .filter(s -> !s.isEmpty())
                                       .count();
        }
        writer.println(maxWordLength + " " + insideWordsCount);
        writer.close();
    }
}
