#include <iostream>
#include <string>
#include <vector>
#include <regex>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // To consume the newline after the integer input
    std::string data;
    std::getline(std::cin, data);

    std::regex regex("\\([\\w_]*\\)");
    std::sregex_token_iterator iter(data.begin(), data.end(), regex, -1);
    std::sregex_token_iterator end;

    int maxWordLength = 0;
    for (; iter != end; ++iter) {
        std::string part = *iter;
        int maxInPart = 0;
        size_t start = 0, endPos;
        while ((endPos = part.find('_', start)) != std::string::npos) {
            int length = endPos - start;
            if (length > maxInPart) {
                maxInPart = length;
            }
            start = endPos + 1;
        }
        // Check the last segment after the last underscore
        int length = part.length() - start;
        if (length > maxInPart) {
            maxInPart = length;
        }
        if (maxInPart > maxWordLength) {
            maxWordLength = maxInPart;
        }
    }

    std::regex pattern("\\([\\w_]*\\)");
    auto matches_begin = std::sregex_iterator(data.begin(), data.end(), pattern);
    auto matches_end = std::sregex_iterator();

    long long insideWordsCount = 0;
    for (auto it = matches_begin; it != matches_end; ++it) {
        std::string match_str = it->str();
        // Remove the parentheses
        std::string inside = match_str.substr(1, match_str.length() - 2);
        size_t start = 0, endPos;
        while ((endPos = inside.find('_', start)) != std::string::npos) {
            std::string s = inside.substr(start, endPos - start);
            if (!s.empty()) {
                ++insideWordsCount;
            }
            start = endPos + 1;
        }
        // Check the last segment after the last underscore
        std::string s = inside.substr(start);
        if (!s.empty()) {
            ++insideWordsCount;
        }
    }

    std::cout << maxWordLength << " " << insideWordsCount << std::endl;
    return 0;
}
